package com.killteamtimer.rules

import android.content.Context
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/**
 * Names and situation tags of every team's rules, generated by tools/rules/build_rules.py from the
 * official Kill Team downloads. Holds no rules text.
 */
@Serializable
data class RulesData(
    val source: String,
    /** Tag id -> label, in display order. */
    val tags: Map<String, String>,
    val universal: List<RuleItem>,
    val teams: List<Team>,
) {
    fun team(id: String?): Team? = teams.firstOrNull { it.id == id }

    companion object {
        private val json = Json { ignoreUnknownKeys = true }

        @Volatile private var cached: RulesData? = null

        fun load(context: Context): RulesData = cached ?: synchronized(this) {
            cached ?: context.assets.open("rules.json").bufferedReader().use { json.decodeFromString<RulesData>(it.readText()) }
                .also { cached = it }
        }
    }
}

@Serializable
data class Team(val id: String, val name: String, val updated: String? = null, val items: List<RuleItem>)

@Serializable
data class RuleItem(
    val id: String,
    val kind: Kind,
    /** Card name, or the operative / faction rule that owns [sub]. */
    val heading: String,
    /** Ability, action or part name within [heading], if any. */
    val sub: String? = null,
    val tags: List<String>,
)

@Serializable
enum class Kind(val label: String) {
    FACTION_RULE("Faction rules"),
    STRATEGY_PLOY("Strategy ploys"),
    FIREFIGHT_PLOY("Firefight ploys"),
    OPERATIVE("Operatives"),
    EQUIPMENT("Equipment"),
}
